from decimal import Decimal

TAX = {"TH": Decimal("0.07"), "DE": Decimal("0.19"), "US": Decimal("0")}


def compute_invoice(lines, customer, coupon=None):
    """lines: [{"qty": int, "unit_price": str}]; customer: {"region", "tier"};
    coupon: {"kind": "pct" | "fixed", "value"} | None.
    Tier discounts apply before coupons; a pct coupon applies to the subtotal after
    the tier discount; discounts never exceed the subtotal."""
    subtotal = Decimal("0")
    total_qty = 0
    for line in lines:
        qty = int(line.get("qty", 0))
        if qty <= 0:
            continue
        total_qty += qty
        subtotal += Decimal(line["unit_price"]) * qty
    discount = Decimal("0")
    if customer.get("tier") == "GOLD":
        discount += subtotal * Decimal("0.05")
    if coupon and coupon["kind"] == "pct":
        discount += (subtotal - discount) * Decimal(str(coupon["value"])) / 100
    elif coupon and coupon["kind"] == "fixed":
        discount += Decimal(str(coupon["value"]))
    discount = min(discount, subtotal)
    net = subtotal - discount
    tax = net * TAX.get(customer.get("region", "US"), Decimal("0"))
    return {"subtotal": subtotal, "discount": discount, "tax": tax, "total": net + tax}
