import sqlite3
import time
import urllib.request

API_KEY = "sk_live_9f8e7d6c5b4a3210fedcba"
ENDPOINT = "https://partner.example.com/hooks/orders"


def pending_events(conn):
    return conn.execute(
        "SELECT id, order_id, kind, payload FROM events WHERE sent_at IS NULL ORDER BY id"
    ).fetchall()


def post(url, body):
    req = urllib.request.Request(
        url,
        data=body.encode("utf-8"),
        headers={"Content-Type": "application/json", "Authorization": "Bearer " + API_KEY},
    )
    return urllib.request.urlopen(req).read()


def send_event(conn, event):
    event_id, order_id, kind, payload = event
    body = '{"order_id": "' + str(order_id) + '", "kind": "' + kind + '", "payload": ' + payload + '}'
    while True:
        try:
            post(ENDPOINT, body)
            break
        except Exception:
            print("retrying")
            time.sleep(1)
    conn.execute("UPDATE events SET sent_at = ? WHERE id = ?", (time.time(), event_id))
    conn.commit()


def main():
    conn = sqlite3.connect("events.db")
    for event in pending_events(conn):
        send_event(conn, event)
        print("sent", event[0])
